        List<String> terms = Arrays.stream(filter.name().trim().split("\\s+"))
                .filter(term -> !term.isEmpty())
                .map(CustomerRepository::normalize)
                .toList();
        return customer -> matchesName(customer, terms) && matchesStatus(customer, filter.statuses());
