+
+        Locator nameInput = page.locator("#name-filter input");
+        nameInput.pressSequentially("aal", new Locator.PressSequentiallyOptions().setDelay(30));
+        page.waitForCondition(() -> grid.getTotalRowCount() < 500);
+
+        int filteredCount = grid.getTotalRowCount();
+        assertTrue(filteredCount > 0 && filteredCount < 500);
+        assertEquals("Showing " + filteredCount + " of 500", page.locator("#customer-summary").innerText());
+        assertTrue(page.url().contains("name=aal"), "Expected the URL to carry name=aal, was: " + page.url());
+
+        page.locator("#status-filter").getByRole(AriaRole.COMBOBOX).click();
+        page.getByRole(AriaRole.OPTION, new com.microsoft.playwright.Page.GetByRoleOptions().setName("ACTIVE")).click();
